import static org.junit.Assert.assertEquals;

public class DeltaTTest {

    @Test
    public void testEstimateForDate_1950To1973() {
        LocalDate forDate = LocalDate.of(1950, 1, 1);
        double deltaT = DeltaT.estimate(forDate);
        assertEquals(0.0344, deltaT, 0.01);
    }

    @Test
    public void testEstimateForDate_1975To2003() {
        LocalDate forDate = LocalDate.of(1975, 6, 1);
        double deltaT = DeltaT.estimate(forDate);
        assertEquals(2.455, deltaT, 0.01);
    }

    @Test
    public void testEstimateForDate_1999To2009() {
        LocalDate forDate = LocalDate.of(1999, 6, 1);
        double deltaT = DeltaT.estimate(forDate);
        assertEquals(3.354, deltaT, 0.01);
    }

    @Test
    public void testEstimateForCurrentDate() {
        Date date = new Date();
        String dateString = (date.toEpochDay() + 1) / 86400000L + "January1";
        LocalDate forDate = LocalDate.of(dateString, 1, 1);
        double deltaT = DeltaT.estimate(forDate);
        assertEquals(0.005, deltaT, 0.001);
    }

    public class DeltaT {

        private static final int MINUTE_IN_DAY = 86400000;

        public static double estimate(LocalDate forDate) {
            long epoch = forDate.atStartOfDay().getEpochSecond();
            return (double) epoch / MINUTE_IN_DAY - 1;
        }
    }
}
